import { useState } from 'react';
import { Recipe } from './types';

// Instagram CDN links expire, so a missing or broken photo falls back to a default
// image for the dish's category (frontend/public/placeholders, generated by
// backend/generate_placeholders.py — slugs must match). First match wins.
export const DISH_IMAGES: [RegExp, string][] = [
  [/batido|smoothie|bebida|drink|jugo|juice|mocktail|latte|caf[eé]|(^|\s)t[eé](\s|$)|limonada/, 'bebidas'],
  [/postre|dessert|dulce|torta|tarta|cake|pastel|galleta|cookie|brownie|brookie|helado|ice cream|paleta|popsicle|mousse|tiramis|chocolate|flan|trufa|galette|parfait|protein balls|energy ball|bolitas/, 'postres'],
  [/avena|oat|ch[ií]a|granola|yogur|yogurt|cottage|reques[oó]n|pancake|panqueque|waffle|huevo|egg|omelet|tortilla espa|shakshuka|frittata/, 'desayunos'],
  [/ensalada|salad|poke|ceviche/, 'ensaladas'],
  [/sopa|soup|caldo|ramen|crema de|gazpacho|pho\b/, 'sopas'],
  [/curry|guiso|estofado|stew|chili|tajine|cazuela|frijol/, 'guisos'],
  [/pasta|spaghetti|espagueti|lasa|ñoqui|gnocchi|fideo|noodle|mac and|macarr|rigatoni|penne|fettucc|ravioli|canel[oó]n/, 'pastas'],
  [/arroz|rice|risotto|paella|quinoa|cusc[uú]s|couscous/, 'arroces'],
  [/salm[oó]n|salmon|at[uú]n\b|\btuna\b|pescado|fish|camar[oó]n|shrimp|sushi|marisco|pulpo|calamar|mejill[oó]n|langost|cangrejo|crab|ostra/, 'comida_de_mar'],
  [/nacho|fries|papas fritas|chips|aperitivo|botana|\bdip\b|palomitas|popcorn|maicitos|snack salado/, 'snacks'],
  [/taco|burrito|quesadilla|empanada|dumpling|gyoza|wrap|sandwich|s[aá]ndwich|pizza|burger|hamburguesa|hot ?dog|perros? caliente|crepe|krep|kebab/, 'comida_rapida'],
  [/pollo|chicken|pavo|turkey|pato|alitas|wings/, 'aves'],
  [/carne|beef|steak|cerdo|pork|cordero|lamb|costilla|ribs|\bres\b|ternera|jam[oó]n|chorizo|salchicha|lomo|chuleta/, 'carnes'],
  [/\bpan\b|bread|focaccia|\bnan\b|naan|quiche|tostada|toast|scone|bagel|cracker/, 'panes'],
  [/verdura|vegetal|vegetable|lenteja|garbanzo|hummus|falafel|tofu|elote|esquite|papa|potato|br[oó]coli|coliflor|berenjena/, 'verduras'],
  // Last: cheese/butter/sauce words also appear in many dishes above.
  [/queso|cheese|brie|burrata|camembert|parmesan|mantequilla|butter|mermelada|\bjam\b|untable|spread|salsa|sauce|aderezo|dressing|ranch|chutney|condimento|sazonador|\bsal\b|pesto|mayo|aioli/, 'untables'],
];
// Title wins over tags: a "desayuno" tag shouldn't turn an omelette into an oat bowl.
// Leftovers are mostly homemade jars (powders, infused honey), closest to the spreads image.
export const dishSlug = (r: Recipe) => {
  // The backend's AI category wins; keywords are the fallback for recipes not yet re-processed.
  if (r.category && DISH_IMAGES.some(([, slug]) => slug === r.category)) return r.category;
  const find = (s: string) => DISH_IMAGES.find(([re]) => re.test(s.toLowerCase()))?.[1];
  return find(`${r.title} ${r.cuisine ?? ''}`) ?? find((r.categories ?? []).join(' ')) ?? 'untables';
};
export default function RecipeImage({ recipe, className }: { recipe: Recipe; className: string }) {
  // Backend photo first (re-extracted, served from /static); a local imageUrl may be an expired
  // Instagram link from an older version. Then the category image, then a plain gradient.
  const sources = [recipe.thumbnail_url, recipe.imageUrl, `/placeholders/${dishSlug(recipe)}.jpg`]
    .filter((s, i, all): s is string => !!s && all.indexOf(s) === i);
  const [stage, setStage] = useState(0);
  const src = sources[stage];
  return (
    <div className={`w-full rounded-xl overflow-hidden relative bg-gradient-to-br from-orange-500/20 to-neutral-800 ${className}`}>
      {src && <img src={src} alt={recipe.title} className="w-full h-full object-cover" referrerPolicy="no-referrer" onError={() => setStage(s => s + 1)} />}
    </div>
  );
}
